    'UI_STRATEGY_FULL_TOOLTIPS' => "Plná záloha obsahuje kompletní obraz virtuálního stroje. Zároveň slouží jako základ pro další ne-plné zálohy. Vzniklý bod obnovy je nazávislý na jiných a tedy samostatně použitelný pro obnovu.",
    'UI_STRATEGY_INCR_TOOLTIPS' => " Přírůstková záloha je typem úlohy, který slouží k záloze dat, která se změnila od poslední (jakékoliv) zálohy. Vzniklý bod obnovy závisí na předchozím bodu obnovy. ",
    'UI_STRATEGY_DIFF_TOOLTIPS' => " Rozdílová záloha je typem úlohy, sloužící k záloze dat, která se změnila od poslední PLNÉ zálohy dat. Vzniklý bod obnovy závisí na bodu obnovy vytvořeném při poslední plné záloze. ",
    'UI_STRATEGY_PINCR_TOOLTIPS' => "永久增量为，在做备份任务时，只需做一次完全备份，以后只做增量备份。永久增量只做一次完全备份，减少完全备份次数，节省备份存储空间及带宽资源",
    'UI_STRATEGY_THREE_TOOLTIPS' => "Obecně doporučujeme provádět plnou zálohu týdně/měsíčně a k tomu denně zálohu přírůstkovou. Nelze vybrat současně zálohu přírůstkovou a rozdílovou. Pokud spustíte jako první zálohu přírůstkovou, nebo rozdílovou, bude tato první úloha automaticky degradována na zálohu plnou. ",
    'UI_STRATEGY_LOG_TOOLTIPS_MYSQL' => "日志备份是在上一次日志备份或完全备份的基础上,对比变化的日志数据",
    'UI_STRATEGY_LOG_TOOLTIPS_SQLSERVER' => "日志备份是在上一次备份的基础上,对变化的日志数据进行备份,依赖于上一个日志时间点或增加时间点或差异时间点或完备时间点",
