    'UI_BACKUP_TRANSPORT_NBD' => "LAN ",
    'UI_BACKUP_TRANSPORT_NBD_XENSERVER' => "NBD",
    'UI_BACKUP_TRANSPORT_NBD_SAN_XENSERVER' => "SAN+NBD",
    'UI_BACKUP_TRANSPORT_NBDSSL' => "Šifrování dat ",
    'UI_BACKUP_TRANSPORT_SAN' => "SAN (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT' => "HOTADD (LAN-Free)",
    'UI_BACKUP_TRANSPORT_HOT_VMWARE' => "HOTADD",
    'UI_BACKUP_TRANSPORT_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.<br><br>SAN (LAN-Free): Zálohovaná data z produktivního úložiště se přenáší pomocí SAN do zálohovacího úložiště. Pro tuto volbu je nutné nejdříve nastavit cestu pro LAN-Free v sekci “Menu->Zdroje->LAN-Free”.<br><br>Šifrování dat: Během přenosu se data šifrují pomocí SSL. <br><br>HOTADD(LAN-Free): Použití vlastnosti VMware disk hot add pro připojení daného disku VM přímo na Vinchin backup server.<br><br>Pokud není dostupný přenos přes SAN, systém automaticky přepne na přenos přes LAN. ",
    'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.<br><br>SAN (LAN-Free): Zálohovaná data z produktivního úložiště se přenáší pomocí SAN do zálohovacího úložiště. Pro tuto volbu je nutné nejdříve nastavit cestu pro LAN-Free v sekci “Menu->Zdroje->LAN-Free”.<br><br>Šifrování dat: Během přenosu se data šifrují pomocí SSL. <br><br>HOTADD: 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问<br><br>Pokud není dostupný přenos přes SAN, systém automaticky přepne na přenos přes LAN. ",
    'UI_BACKUP_TRANSPORT_ICS_VVDK_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.",
    'UI_BACKUP_TRANSPORT_SELECT_NBD_TIPS' => '【网络会自动切换，若有专用备份网络则优先使用专用网络传输，否则才会切换至管理网络进行传输】',
    'UI_BACKUP_TRANSPORT_HUAWEI_KVM_SELECT_TIPS' => "NBD传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_RHV_SELECT_TIPS' => "网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>ImageIO传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质",
    'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.<br><br>SAN (LAN-Free): Zálohovaná data z produktivního úložiště se přenáší pomocí SAN do zálohovacího úložiště. Pro tuto volbu je nutné nejdříve nastavit cestu pro LAN-Free v sekci “Menu->Zdroje->LAN-Free”.<br><br>Šifrování dat: Během přenosu se data šifrují pomocí SSL.<br><br>Pokud není dostupný přenos přes SAN, systém automaticky přepne na přenos přes LAN. ",
    'UI_BACKUP_TRANSPORT_LEIXEN_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.<br><br>SAN (LAN-Free): Zálohovaná data z produktivního úložiště se přenáší pomocí SAN do zálohovacího úložiště. Pro tuto volbu je nutné nejdříve nastavit cestu pro LAN-Free v sekci “Menu->Zdroje->LAN-Free”.<br><br>Pokud není dostupný přenos přes SAN, systém automaticky přepne na přenos přes LAN. ",
    'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS' => "LAN: Zálohovaná data z produktivního úložiště se přenáší pomocí LAN do zálohovacího úložiště.<br><br>SAN (LAN-Free): Zálohovaná data z produktivního úložiště se přenáší pomocí SAN do zálohovacího úložiště. Pro tuto volbu je nutné nejdříve nastavit cestu pro LAN-Free v sekci “Menu->Zdroje->LAN-Free”. <br><br>NBD: Zálohovaná data se přenesou pomocí NBD, podporováno jest v XenServer7.3 a výše<br><br>SAN+NBD:Zálohovaná data se přenesou pomocí NBD+SAN<br><br>Pokud není dostupný přenos přes SAN, systém automaticky přepne na přenos přes LAN. ",
    'UI_BACKUP_TRANSPORT_HOTADD' => "Přenos přes HotAdd ",
