    'UI_BACKUP_MODE_HIGH_SPEED' => "SpeedKit ",
    'UI_BACKUP_MODE_HIGH_SPEED_TIPS' => "SpeedKit zvyšuje rychlost propočítávání změněných bloků při přírůstkových zálohách. Doporučujeme zapnout, chcete-li rychlejší zálohy. (Předpoklad: Dostatečné místo v úložišti.) <br><br>SpeedKit does not support Proxy.",
    'UI_BACKUP_INC_MODE_TIPS' => "SpeedKit je technologie firmy Vinchin sloužící ke zrychlení zjištění změněných bloků při přírůstkových zálohách. Zapněte ji, chcete-li rychlejší zálohya pokud nemůžete použít CBT.<br><br>CBT je technologie firmy Citrix sloužící ke zrychlení přírůstkových záloh, XenServer 7.3 a vyšší ji podporují (licence nutná) <br><br> Běžný módy: Přírústková záloha bude trvat déle.",
    'UI_BACKUP_INC_MODE_TIPS_EN' => "SpeedKit is a Vinchin technology to improve the computing speed of changed blocks when doing incremental backups. It is recommended to be selected if you want a faster backup or when CBT doesn’t work. (Precondition: Make sure your storage space is large enough.) <br><br> Ordinary: Take more time to do incremental backups.",
    'UI_BACKUP_INC_MODE_CTB_TIPS' => "CBT je technologie firmy Citrix sloužící ke zrychlení přírůstkových záloh, XenServer 7.3 a vyšší ji podporují (licence nutná) ",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT' => "Quiesced snapshot",
    'UI_BACKUP_MODE_HIGH_SILENTSNAPSHOT_TIPS' => "Povolením “Quiesced Snapshot” zajistíte snapshot, o kterém se dozví samotná VM a tedy i aplikace, která může vhodně zareagovat a učinit tak snapshot datově konsistentním. Pro tento způsob je zapotřebí splnit jisté předpoklady - agenta na straně VM (např. VMware Tools). <br><br> Dále pak aplikace na Windows OS musí podporovat technologii Microsoft VSS. <br><br> selže-li quiesced snapshot, systém provede snapshot normální. ",
    'UI_BACKUP_MODE_HIGH_HUAWEI_KVM_SILENTSNAPSHOT_TIPS' => "一致性快照可以通过应用感知程序,使文件系统或应用处于一致性状态<br><br>Windows操作系统需要应用支持VSS,才能保证应用的数据一致性<br><br>开启一致性快照后如果打一致性快照失败将自动再尝试打非一致性快照",
    'UI_BACKUP_MODE_HIGH_CBT_TIPS' => "Povolení “CBT” může zrychlit přírústkové zálohy. Podporováno virtuálními stroji od verze 7..",
    'UI_BACKUP_MODE_HIGH_SNAPSHOT_TIPS' => "Sériově: Snapshot a přenos dat VM postupně. <br><br>Paralelně: Vytvoření snapshotu všech VM v rámci úlohy zároveň a následně přenos dat. Doporučeno jen v případě aplikační závislosti mezi VM, kdy se předpokládá potřeba obnovy více VM do stejného časového okamžiku. ",
    'UI_BACKUP_MODE_HIGH_VCBT_TIPS' => "Povolit BitDetector, který může snížit velikost zálohy a zatížení sítě.",
    'UI_BACKUP_MODE_HIGH_SWAP_TIPS' => "Swapovací soubor se používá k odkládání aktuálně nepotřebných bloků v paměti RAM. Na úrovni Windows se jedná o soubory pagefile.sys/hiber.sys. Zálohovat tato data nemá smysl. ",
    'UI_BACKUP_MODE_HIGH_DELFILE_TIPS' => "Povolením této volby se ze zálohování vynechají soubory v odpadkovém koši a smazané soubory.",
